head.script:
// ===== 리턴 값 출력 영역 =====
scwin.btn_clear_onclick = function (e) {
    $p.getComponentById("tbx_return").setValue("");
};

scwin.setReturnValue = function (strValue) {
    var objReturn = $p.getComponentById("tbx_return");
    objReturn.setValue(objReturn.getValue() + strValue);
    objReturn.setValue(objReturn.getValue() + "\n");
};

// ===== 결함 재현 (5.0 vs 6.0 동작 비교) =====

// 입력란에서 포커스가 빠져나간 시점의 값을 기록한다.
//  입력 중에는 두 버전 모두 소수점이 찍히고, 포커스 이탈 시점에 정리되는지가 갈린다.
scwin.report = function (strId, strLen, strDesc) {
    var strValue = $p.getComponentById(strId).getText();
    var bDot = (String(strValue).indexOf(".") >= 0);

    scwin.setReturnValue("=====maxlength=\"" + strLen + "\" (" + strDesc + ")=====");
    scwin.setReturnValue("    포커스 이탈 후 값 : " + strValue);
    scwin.setReturnValue("    소수점 남음 : " + (bDot ? "O" : "X"));
    scwin.setReturnValue("");
};

scwin.input1_onblur = function (e) {
    scwin.report("input1", "5", "\".\" 없이 숫자만 설정 - 소수부 입력 불가");
};

scwin.input2_onblur = function (e) {
    scwin.report("input2", "*", "정수부만 제한 없이 입력");
};

scwin.input3_onblur = function (e) {
    scwin.report("input3", "*.", "정수부만 제한 없이 입력");
};
